import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSimlipalData(){const e=readFileSync(resolve(__dirname,"../../frontend/simlipal-national-park-explorer/simlipal-data.js"),"utf-8");return new Function(e+"\nreturn { SIMLIPAL_INFO, WATERFALLS, MELANISTIC_TIGERS, ELEPHANTS_WILDLIFE, FOREST_TYPES, TRIBAL_COMMUNITIES, HISTORY_TIMELINE, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadNationalParksData(){const e=readFileSync(resolve(__dirname,"../../frontend/national-parks-explorer/data.js"),"utf-8");return new Function(e+"\nreturn { NATIONAL_PARKS, STATES };")()}function loadSearchIndex(){const e=readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8");return new Function("window",e+"\nreturn window.indiaSearchIndex;")({})}describe("Simlipal National Park Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadSimlipalData()}),describe("SIMLIPAL_INFO metadata & WATERFALLS",()=>{it("contains correct park metadata for Simlipal",()=>{expect(e.SIMLIPAL_INFO.id).toBe("simlipal"),expect(e.SIMLIPAL_INFO.name).toBe("Simlipal National Park"),expect(e.SIMLIPAL_INFO.state).toBe("Odisha"),expect(e.SIMLIPAL_INFO.establishedYear).toBe(1980),expect(e.SIMLIPAL_INFO.biosphereYear).toBe(2009),expect(e.SIMLIPAL_INFO.coordinates.lat).toBeCloseTo(21.9333,2),expect(e.SIMLIPAL_INFO.coordinates.lng).toBeCloseTo(86.35,2)}),it("WATERFALLS includes Barehipani (399m) and Joranda (181m)",()=>{expect(Array.isArray(e.WATERFALLS)).toBe(!0),expect(e.WATERFALLS.length).toBe(2);const t=e.WATERFALLS.find(e=>"barehipani"===e.id),a=e.WATERFALLS.find(e=>"joranda"===e.id);expect(t).toBeDefined(),expect(t.height).toContain("399"),expect(a).toBeDefined(),expect(a.height).toContain("181")})}),describe("MELANISTIC_TIGERS & ELEPHANTS_WILDLIFE",()=>{it("MELANISTIC_TIGERS details Black Tiger genetic facts",()=>{expect(e.MELANISTIC_TIGERS.title).toContain("Melanistic"),expect(e.MELANISTIC_TIGERS.genetics).toContain("gene mutation"),expect(e.MELANISTIC_TIGERS.conservationStatus).toContain("60%")}),it("ELEPHANTS_WILDLIFE includes Asian Elephant and Sambar Deer",()=>{expect(Array.isArray(e.ELEPHANTS_WILDLIFE)).toBe(!0),expect(e.ELEPHANTS_WILDLIFE.length).toBeGreaterThanOrEqual(4);const t=e.ELEPHANTS_WILDLIFE.find(e=>"asian-elephant"===e.id);expect(t).toBeDefined()})}),describe("FOREST_TYPES & TRIBAL_COMMUNITIES",()=>{it("FOREST_TYPES includes 94+ Orchid species and Sal forests",()=>{expect(Array.isArray(e.FOREST_TYPES)).toBe(!0),expect(e.FOREST_TYPES.length).toBe(4);const t=e.FOREST_TYPES.find(e=>"forest-orchids"===e.id);expect(t).toBeDefined(),expect(t.name).toContain("94+")}),it("TRIBAL_COMMUNITIES showcases Santhal, Ho, Mankidia, Khadia",()=>{expect(Array.isArray(e.TRIBAL_COMMUNITIES)).toBe(!0),expect(e.TRIBAL_COMMUNITIES.length).toBeGreaterThanOrEqual(4);const t=e.TRIBAL_COMMUNITIES.find(e=>e.name.includes("Santhal"));expect(t).toBeDefined()})}),describe("MAP_HOTSPOTS & HISTORY_TIMELINE",()=>{it("MAP_HOTSPOTS has valid percentage coordinates (0-100)",()=>{expect(Array.isArray(e.MAP_HOTSPOTS)).toBe(!0),expect(e.MAP_HOTSPOTS.length).toBeGreaterThanOrEqual(5),e.MAP_HOTSPOTS.forEach(e=>{expect(e.x).toBeGreaterThanOrEqual(0),expect(e.x).toBeLessThanOrEqual(100),expect(e.y).toBeGreaterThanOrEqual(0),expect(e.y).toBeLessThanOrEqual(100)})}),it("HISTORY_TIMELINE includes 1973 Project Tiger and 2009 UNESCO Biosphere",()=>{expect(Array.isArray(e.HISTORY_TIMELINE)).toBe(!0),expect(e.HISTORY_TIMELINE.length).toBeGreaterThanOrEqual(4)})}),describe("Landing Page & Search Index Integration",()=>{it("Simlipal entry in NATIONAL_PARKS has explorerUrl",()=>{const e=loadNationalParksData().NATIONAL_PARKS.find(e=>"simlipal"===e.id);expect(e).toBeDefined(),expect(e.explorerUrl).toBe("../simlipal-national-park-explorer/index.html"),expect(e.state).toBe("Odisha")}),it("Search Index registers Simlipal National Park Explorer",()=>{const e=loadSearchIndex().find(e=>"Simlipal National Park Explorer"===e.title);expect(e).toBeDefined(),expect(e.url).toBe("frontend/simlipal-national-park-explorer/index.html")})})});